// Initialize a simple Git repository simulation
import java.nio.file.*;
import java.io.IOException;

public class GitBranchDemo {
    public static void main(String[] args) throws IOException {
        // Simulate what happens internally when creating a branch
        var gitRefsHeads = Path.of(".git/refs/heads");

        // Creating 'main' branch - just a file with commit hash
        var mainBranch = gitRefsHeads.resolve("main");
        Files.writeString(mainBranch, "a3f2b891c456def7890abcdef1234567890abcde\n");

        // Creating 'feature-login' branch - copies current commit hash
        var featureBranch = gitRefsHeads.resolve("feature-login");
        String currentCommit = Files.readString(mainBranch).trim();
        Files.writeString(featureBranch, currentCommit + "\n"); // Same commit, new pointer

        // HEAD file tracks which branch is active
        var headFile = Path.of(".git/HEAD");
        Files.writeString(headFile, "ref: refs/heads/feature-login\n"); // Points to branch file

        System.out.println("Branch created in ~1ms, no code copied");
    }
}

// Typical feature branch lifecycle for a Java Spring Boot project
// Developer creates branch for new user registration feature

// 1. Start from updated main branch
// git checkout main
// git pull origin main

// 2. Create feature branch
// git switch -c feature/user-registration

@RestController
@RequestMapping("/api/users")
public class UserController {

    private final UserService userService;

    // Develop and commit feature incrementally
    @PostMapping("/register")
    public ResponseEntity<UserResponse> registerUser(@RequestBody UserRequest request) {
        var user = userService.createUser(request); // Feature code isolated here
        return ResponseEntity.status(HttpStatus.CREATED).body(user);
    }
}

// 3. Push feature branch to remote
// git push origin feature/user-registration

// 4. Open pull request on GitHub/GitLab for code review
// 5. After approval and CI tests pass, merge to main
// 6. Delete feature branch - work is now in main

// Common branch operations in a Java project development cycle
import java.io.*;

public class BranchOperationsExample {
    public static void main(String[] args) throws IOException {
        // Simulate executing Git commands in a terminal
        var commands = new ProcessBuilder();

        // List all local branches (current marked with *)
        // git branch
        // Output: * main
        //         feature/payment-gateway

        // List all branches including remote tracking branches
        // git branch -a
        // Output shows origin/main, origin/feature/user-auth, etc.

        // Create and switch to new feature branch (modern approach)
        // git switch -c feature/order-processing

        // Alternative: create without switching
        // git branch feature/email-notifications

        // Safe delete a merged branch (prevents accidental data loss)
        // git branch -d feature/payment-gateway
        // Error if unmerged: "branch not fully merged"

        // Force delete (dangerous - use only when certain)
        // git branch -D feature/abandoned-experiment

        System.out.println("Branch operations complete");
    }
}

// Demonstrating what HEAD actually contains
import java.nio.file.*;
import java.io.IOException;

public class HeadPointerDemo {
    public static void main(String[] args) throws IOException {
        // Read the HEAD file to see what it points to
        var headFile = Path.of(".git/HEAD");
        String headContent = Files.readString(headFile);
        System.out.println("HEAD contains: " + headContent);
        // Output: "ref: refs/heads/main" (points to branch)

        // Read what that branch points to
        var mainBranch = Path.of(".git/refs/heads/main");
        String commitHash = Files.readString(mainBranch).trim();
        System.out.println("main branch points to commit: " + commitHash);
        // Output: "a3f2b891c456..." (40-char SHA-1)

        // When you switch branches, HEAD changes
        // git switch feature-login
        // Now HEAD would contain: "ref: refs/heads/feature-login"

        // Detached HEAD: checking out a specific commit
        // git checkout a3f2b891
        // HEAD now contains the commit hash directly, not a branch reference
        var detachedHead = "a3f2b891c456def7890abcdef1234567890abcde";
        System.out.println("Detached HEAD: " + detachedHead); // No branch reference
    }
}
